9:["Why can a smoker run for a bus at 20 but not at 50?","sim:breathing",[["Health","Tuberculosis, often linked with HIV, remains a major disease of the lungs in Zambia."],["Mining","Silicosis and dust-related lung disease affect miners on the Copperbelt."],["Lifestyle","Smoking destroys alveolar walls (emphysema) and cilia."]],[4,8,9,10],["How is the gas exchange system organised?","Which tissues are found where?","How does structure help gas exchange?"]],
10:["Malaria, TB, HIV and cholera together cause most infectious deaths in Zambia. What do they have in common, and how are they controlled?","emo:🦟 🫁 🩸 💧|Four diseases, four ways of spreading.",[["Public health","Insecticide-treated nets and indoor spraying have cut malaria deaths in Zambia."],["Medicine","Antibiotic resistance threatens TB treatment; multidrug-resistant TB needs long, costly treatment."],["Society","Antiretroviral therapy has transformed HIV from a death sentence into a manageable condition."]],[10,11,17,19],["How are the major infectious diseases transmitted?","How can they be prevented and controlled?","How do antibiotics work and why does resistance arise?"]],
11:["Why did smallpox disappear from the world, but malaria has not, even though both have killed millions?","sim:immunity",[["Medicine","Zambia’s childhood vaccines protect against measles, polio, TB and more."],["Diagnostics","Rapid malaria and HIV tests use monoclonal antibodies."],["Research","Malaria vaccines (RTS,S and R21) are now being rolled out in parts of Africa."]],[10,11,16,19],["How do phagocytes and lymphocytes defend the body?","How do antibodies and monoclonal antibodies work?","How do vaccines control disease?"]],
12:["Why can rice grow in flooded paddies where most plants’ roots would rot?","sim:etc",[["Sport","Athletes measure respiratory quotient and lactate to plan training."],["Agriculture","Rice paddies in Zambia’s wetlands (for example Mongu) depend on rice’s anaerobic adaptations."],["Industry","Yeast fermentation produces ethanol fuel from sugar cane."]],[1,3,12,13],["What is ATP and how is it made?","What happens in each stage of aerobic respiration?","How do organisms respire without oxygen?"]],
13:["Leaves are green because they reflect green light. So which colours do they actually use?","sim:lightdep",[["Food security","Understanding limiting factors helps greenhouse farmers near Lusaka raise yields."],["Climate","Photosynthesis removes carbon dioxide; deforestation for charcoal reduces this sink."],["Research","Scientists are trying to improve the efficiency of rubisco to boost crop yields."]],[2,12,13,14],["How is light energy converted to chemical energy?","What happens in the light-dependent and light-independent stages?","How do limiting factors affect the rate?"]],
14:["Why does a person with diabetes test their urine or blood, while a healthy person never needs to?","sim:glucose",[["Health","Diabetes and kidney disease are rising in Zambia, linked to diet and lifestyle."],["Medicine","Biosensors and test strips let patients monitor their own glucose."],["Agriculture","Plants close stomata using abscisic acid during drought."]],[8,14,15],["What is homeostasis and how does negative feedback work?","How does the kidney make urine and regulate water?","How are blood glucose and stomatal opening controlled?"]],
15:["How can a nerve impulse travel at 100 metres per second, and what makes a Venus flytrap snap shut?","sim:actionpotential",[["Medicine","Nerve agents and many insecticides act at synapses."],["Health","Multiple sclerosis damages myelin and slows impulses."],["Agriculture","Gibberellins are used in brewing to germinate barley evenly."]],[4,14,15,16],["How are action potentials produced and transmitted?","How do synapses and muscles work?","How do plants coordinate responses?"]],
16:["Why can two brown-eyed parents have a blue-eyed child, and why are some genes switched off?","sim:genetics",[["Health","Sickle cell disease is common in Zambia; genetic counselling helps families."],["Agriculture","Dihybrid crosses help breeders combine disease resistance and yield."],["Biotechnology","The lac operon was the first gene control system discovered and is used in genetic engineering."]],[5,6,16,17],["How does meiosis produce variation?","How do we predict and test inheritance patterns?","How are genes switched on and off?"]],
17:["How did the mosquitoes that carry malaria become resistant to insecticides?","sim:selection",[["Health","Insecticide resistance in Anopheles mosquitoes threatens malaria control in Zambia."],["Medicine","Antibiotic resistance spreads by natural selection."],["Agriculture","Selective breeding produced drought-tolerant maize and high-yield cattle."]],[16,17,18],["How do we measure and compare variation?","How does natural selection change allele frequencies?","How do new species arise?"]],
18:["Zambia has around 230 mammal species and many more plants and insects. How do ecologists measure biodiversity?","sim:quadrats",[["Conservation","Zambia’s national parks and game management areas protect species such as lechwe, wild dog and elephant."],["Research","Simpson’s index helps compare habitats such as miombo woodland and dambos."],["Policy","Zambia is a party to CITES, controlling trade in endangered species such as pangolins."]],[1,17,18,19],["How are organisms classified into domains and kingdoms?","How do we sample and measure biodiversity?","How do correlation tests show links between species and conditions?"]],
19:["How can scientists take a gene from one organism and make it work in another?","sim:pcrgel",[["Medicine","Recombinant insulin, vaccines and PCR tests save lives every day."],["Forensics","DNA profiling solves crimes and paternity cases."],["Agriculture","Zambia’s Biosafety Act controls the use of GM crops."]],[6,16,19],["How is recombinant DNA made?","How are PCR, gel electrophoresis and gene editing used?","What are the benefits and risks of genetic technology?"]]
